/**
 * Calculate increment/decrement step.
 *
 * The step calculation formula is: 1 divided by Math.pow(base, exponent).
 *
 * Variable base = 10.
 * Variable exponent = decimal length.
 *
 * Example:
 * 18 will return 1, formula: 1 / Math.pow(10, 0)
 * 1.4 will return 0.1, formula: 1 / Math.pow(10, 1)
 * 2.63 will return 0.01, formula: 1 / Math.pow(10, 2)
 * 7.396 will return 0.001, formula: 1 / Math.pow(10, 3).
 *
 * @since ??
 *
 * @param {string | number} value The value to calculate.
 *
 * @returns {number}
 */
export declare const calculateStep: (value: string | number) => number;
